window.CAPTIONS_TIMING = [{"id":"c01","t0":0.6,"t1":4.11,"text":"Your client asks for a change, in chat."},{"id":"c02","t0":4.36,"t1":8.27,"text":"Usually this is where the form, the queue and the wait begin."},{"id":"c03","t0":8.52,"t1":12.26,"text":"Tally reads the thread instead. The message is the request."},{"id":"c04","t0":13.4,"t1":18.07,"text":"It finds the client in your CRM and recalls their deal and your price list."},{"id":"c05","t0":18.4,"t1":22.37,"text":"The part that makes this safe: the model reads and asks."},{"id":"c06","t0":22.62,"t1":26.39,"text":"Code decides and pays, inside a written policy."},{"id":"c07","t0":26.64,"t1":30.03,"text":"Code checks the clauses and creates the Stripe invoice:"},{"id":"c08","t0":30.28,"t1":34.32,"text":"five thousand pounds, yearly, due in seven days."},{"id":"c09","t0":34.57,"t1":40.21,"text":"The client gets the reply and the PDF in the same chat. They never left it."},{"id":"c10","t0":42.4,"t1":47.95,"text":"Every pound carries a receipt: their words, the remembered fact, the clause."},{"id":"c11","t0":50.4,"t1":55.05,"text":"Your team gets a note, not a ticket. The books stay right."},{"id":"c12","t0":56.4,"t1":60.83,"text":"Now change one thing. A dispute crosses a written limit."},{"id":"c13","t0":61.08,"t1":64.34,"text":"Code stops and asks a human, in the same chat."},{"id":"c14","t0":64.59,"t1":67.13,"text":"One word pauses everything."},{"id":"c15","t0":67.4,"t1":69.76,"text":"Said. Done. Billed."},{"id":"c16","t0":70.01,"t1":74.36,"text":"The conversation is the contract. The agent is the back office."}]
